    DEF A RigidBody {
      fixed TRUE
      position 0 5 0
      geometry DEF A_C CollidableShape {
        translation 0 5 0
        shape Shape {
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      }
    }
    DEF B RigidBody {
      position 1.499989 4.994172 0
      orientation 0 0 -1.00000000000727 0.0038853727364343
      linearVelocity -0.001234634 -0.3078499 0
      angularVelocity 0 0 -0.2052107
      geometry DEF B_C CollidableShape {
        translation 1.499989 4.994172 0
        rotation 0 0 -1.00000000000727 0.0038853727364343
        shape Shape {
          geometry Box {
            size 3 0.4 0.4
          }
        }
      }
    }
    DEF C RigidBody {
      position 0.9999731 4.992637 6
      orientation 0 0 -0.999999999997351 0.00736340926949443
      linearVelocity -0.002910269 -0.388933 0
      angularVelocity 0 0 -0.3889375
      geometry DEF C_C CollidableShape {
        translation 0.9999731 4.992637 6
        rotation 0 0 -0.999999999997351 0.00736340926949443
        shape Shape {
          geometry Sphere {
            radius 0.3
          }
        }
      }
    }
  ]
  joints [
    DEF J SingleAxisHingeJoint {
      forceOutput [
        "angle",
        "angleRate",
        "body2AnchorPoint"
      ]
      anchorPoint 0 5 0
      axis 0 0 1
      body1 USE A
      body2 USE B
