      anchorPoint 0 5 6
      body1 USE A
      body2 USE C
    }
  ]
}

DEF TS TimeSensor {
  loop TRUE
}

DEF SC Script {
  inputOnly      SFTime   tick
  outputOnly     SFVec3f  an
  outputOnly     SFVec3f  ax
  outputOnly     SFFloat  mn
  outputOnly     MFString fo
  initializeOnly SFFloat  s0 9.466848e8

  url "ecmascript:
